--
-- Name: get_user_skill_percentages_by_user_temp(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_user_skill_percentages_by_user_temp(p_user_id integer) RETURNS TABLE(user_id integer, user_name character varying, leadership_percent numeric, management_percent numeric, cognitive_percent numeric)
    LANGUAGE plpgsql
    AS $$
DECLARE
    max_response_value NUMERIC := 5.0;
BEGIN
    RETURN QUERY
    SELECT 
        u.user_id,
        u.user_name,
        ROUND(SUM(CAST(ur.response_value AS NUMERIC) * COALESCE(q.leadership_weight, 0)) / NULLIF(max_response_value * SUM(COALESCE(q.leadership_weight, 0)), 0) * 100, 2) AS leadership_percent,
        ROUND(SUM(CAST(ur.response_value AS NUMERIC) * COALESCE(q.management_weight, 0)) / NULLIF(max_response_value * SUM(COALESCE(q.management_weight, 0)), 0) * 100, 2) AS management_percent,
        ROUND(SUM(CAST(ur.response_value AS NUMERIC) * COALESCE(q.cognitive_weight, 0)) / NULLIF(max_response_value * SUM(COALESCE(q.cognitive_weight, 0)), 0) * 100, 2) AS cognitive_percent
    FROM user_responses ur
    JOIN users u ON ur.user_id = u.user_id
    JOIN questions q ON ur.question_id = q.question_id
    WHERE ur.user_id = p_user_id
    GROUP BY u.user_id, u.user_name;
END;
$$;


ALTER FUNCTION public.get_user_skill_percentages_by_user_temp(p_user_id integer) OWNER TO postgres;

